import java.io.*;

public class Main {
    private static final int IBUF_SIZE = 1 << 16;
    private static final byte[] ibuf = new byte[IBUF_SIZE];
    private static int ipos = 0, ilen = 0;
    private static final InputStream is = System.in;

    private static int readByte() throws IOException {
        if (ipos == ilen) {
            ilen = is.read(ibuf, 0, IBUF_SIZE);
            ipos = 0;
            if (ilen <= 0) return -1;
        }
        return ibuf[ipos++];
    }

    private static int nextInt() throws IOException {
        int c = readByte();
        while (c != -1 && (c < '0' || c > '9')) c = readByte();
        int x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int m = nextInt();
        int p = nextInt();

        // rowFrom[i] = linha original cujo conteúdo está agora na linha i
        // colFrom[j] = coluna original cujo conteúdo está agora na coluna j
        int[] rowFrom = new int[n + 1];
        for (int i = 1; i <= n; i++) rowFrom[i] = i;
        int[] colFrom = new int[m + 1];
        for (int j = 1; j <= m; j++) colFrom[j] = j;

        for (int k = 0; k < p; k++) {
            int c = readByte();
            while (c != 'L' && c != 'C') {
                if (c == -1) break;
                c = readByte();
            }
            int a = nextInt();
            int b = nextInt();
            if (c == 'L') {
                int t = rowFrom[a]; rowFrom[a] = rowFrom[b]; rowFrom[b] = t;
            } else if (c == 'C') {
                int t = colFrom[a]; colFrom[a] = colFrom[b]; colFrom[b] = t;
            }
        }

        OutputStream os = new BufferedOutputStream(System.out, 1 << 16);
        byte[] buf = new byte[1 << 16];
        int bufLen = buf.length;
        int bufIdx = 0;

        for (int i = 1; i <= n; i++) {
            int base = (rowFrom[i] - 1) * m;
            for (int j = 1; j <= m; j++) {
                int val = base + colFrom[j];
                if (bufIdx + 9 > bufLen) {
                    os.write(buf, 0, bufIdx);
                    bufIdx = 0;
                }
                int start = bufIdx;
                do {
                    buf[bufIdx++] = (byte) ('0' + val % 10);
                    val /= 10;
                } while (val > 0);
                for (int l = start, r = bufIdx - 1; l < r; l++, r--) {
                    byte t = buf[l]; buf[l] = buf[r]; buf[r] = t;
                }
                buf[bufIdx++] = (j < m) ? (byte) ' ' : (byte) '\n';
            }
        }
        os.write(buf, 0, bufIdx);
        os.flush();
    }
}
